import{f as t,o as e,c as i,a4 as o}from"./chunks/framework.6QvN0vQS.js";const O=JSON.parse('{"title":"Casos de prueba de aceptación — M15 CON — Contabilidad, centros de costo, múltiples planes de cuentas, escenarios simulados y presupuestos","description":"","frontmatter":{},"headers":[],"relativePath":"entregables-analisis-diseno/20-casos-prueba/M15-CON-contabilidad.md","filePath":"entregables-analisis-diseno/20-casos-prueba/M15-CON-contabilidad.md","lastUpdated":null}'),d={name:"entregables-analisis-diseno/20-casos-prueba/M15-CON-contabilidad.md"};function n(c,a,r,s,l,u){return e(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="casos-de-prueba-de-aceptacion-—-m15-con-—-contabilidad-centros-de-costo-multiples-planes-de-cuentas-escenarios-simulados-y-presupuestos" tabindex="-1">Casos de prueba de aceptación — M15 CON — Contabilidad, centros de costo, múltiples planes de cuentas, escenarios simulados y presupuestos <a class="header-anchor" href="#casos-de-prueba-de-aceptacion-—-m15-con-—-contabilidad-centros-de-costo-multiples-planes-de-cuentas-escenarios-simulados-y-presupuestos" aria-label="Permalink to &quot;Casos de prueba de aceptación — M15 CON — Contabilidad, centros de costo, múltiples planes de cuentas, escenarios simulados y presupuestos&quot;">​</a></h1><p>Parte de <a href="./../20-casos-prueba"><code>20-casos-prueba.md</code></a> (artefacto 9.2). Fuente: <a href="./../../especificacion/anexos/M15-CON-contabilidad"><code>M15-CON-contabilidad.md</code></a> (solo lectura). Generado por <code>_trabajo/gen_casos_prueba.py</code> y revisado; ante diferencias prevalece el anexo.</p><p>Resumen: 162 CP de requisitos funcionales, 31 CP de escenarios ESC y 21 CP de casos de uso CU.</p><p>Convenciones: el formato Dado / Cuando / Entonces sigue <code>07-estrategia-pruebas.md</code> §13; la ola de un CP de RF es la del prompt que lo implementa en <code>03</code> (prevalece sobre la columna del anexo); la de un CP de escenario es la última ola de los RF que cita o la que el escenario declara. Prioridad Extensión del anexo se agrupa como Estándar. Todos los datos son ficticios (TEN-001, TEN-002 y semillas del §18 del anexo).</p><h2 id="_1-casos-por-requisito-funcional" tabindex="-1">1. Casos por requisito funcional <a class="header-anchor" href="#_1-casos-por-requisito-funcional" aria-label="Permalink to &quot;1. Casos por requisito funcional&quot;">​</a></h2><p>Precondiciones comunes de esta sección: ola indicada desplegada en <code>staging</code> o <code>sandbox</code>; tenant ficticio TEN-001 con la configuración publicada y las semillas del M15 §18; usuario con la capability que exige el RF (el caso negativo sin capability lo cubre la suite de permisos negativos, <code>07</code> §4.3). Resultado esperado: el criterio de aceptación del RF se cumple, la prueba automatizada cita el RF y el CP en su nombre, y quedan auditoría y evento cuando hay cambio persistente.</p><h3 id="_1-1-configuracion-general-m15-§5-1" tabindex="-1">1.1 Configuración general (M15 §5.1) <a class="header-anchor" href="#_1-1-configuracion-general-m15-§5-1" aria-label="Permalink to &quot;1.1 Configuración general (M15 §5.1)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CON-0001</td><td>RF-CON-001; M15 §5.1; PRO-O5-10</td><td>O5</td><td>Núcleo</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Configuración contable por tenant: plan operativo vigente, moneda funcional ARS, zona horaria, formato de numeración de asientos, decimales de porcentajes de centros, activación de centros de costo (general o solo sueldos), tolerancia de…</td><td>La configuración se publica versionada (T04) y cada asiento registra la versión aplicada.</td></tr><tr><td>CP-CON-0002</td><td>RF-CON-002; M15 §5.1; PRO-O5-10</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Modo de contabilización por módulo de origen: <strong>tiempo real</strong> (un asiento por operación al recibir el evento), <strong>resumen diario</strong> o <strong>resumen por rango</strong> (los eventos quedan en bandeja y un lote los agrega), sin que ningún evento pueda…</td><td>Con modo resumen diario, 1.000 facturas del día generan un asiento por servicio y concepto vinculado a los 1.000 eventos; reprocesar el día no duplica.</td></tr><tr><td>CP-CON-0003</td><td>RF-CON-003; M15 §5.1; PRO-O5-10</td><td>O5</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Fecha contable base por módulo: emisión, fecha contable del comprobante de compra (<code>FEC_CON</code>), fecha de acreditación, fecha de confirmación del pago o cierre de caja; opción de usar fecha de emisión en ventas.</td><td>Cambiar la base solo afecta eventos no contabilizados y queda auditado.</td></tr><tr><td>CP-CON-0004</td><td>RF-CON-004; M15 §5.1; PRO-O5-10</td><td>O5</td><td>Núcleo</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Roles de cuenta tipados por plan (cuentas por defecto del motor) que reemplazan los parámetros-cuenta P513, P2101–P2167 y P3141, más roles nuevos de GoodApps (§14.2).</td><td>Cada rol apunta a una cuenta imputable del plan; un rol sin cuenta aparece en el validador.</td></tr><tr><td>CP-CON-0005</td><td>RF-CON-005; M15 §5.1; PRO-O5-10</td><td>O5</td><td>Núcleo</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Validador de salud de la configuración contable (&quot;cuentas sin asignar&quot;): lista cada rol, regla, entidad o combinación de dimensiones sin cuenta resoluble, con el enlace a la pantalla donde se configura; corre a demanda, al publicar…</td><td>Un servicio nuevo sin cuenta de ingresos aparece en el validador antes de su primera factura.</td></tr><tr><td>CP-CON-0006</td><td>RF-CON-006; M15 §5.1; PRO-O5-10</td><td>O5</td><td>Estándar</td><td>seguridad</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>La publicación de configuración de un servicio, concepto, impuesto, medio de pago, banco, caja o grupo contable nuevo advierte (o bloquea, según política) si no tiene regla de imputación resuelta en el plan operativo.</td><td>Copiar Internet a otro tenant sin equivalencia contable detiene la publicación con el detalle faltante.</td></tr></tbody></table><h3 id="_1-2-planes-de-cuentas-y-cuentas-m15-§5-2" tabindex="-1">1.2 Planes de cuentas y cuentas (M15 §5.2) <a class="header-anchor" href="#_1-2-planes-de-cuentas-y-cuentas-m15-§5-2" aria-label="Permalink to &quot;1.2 Planes de cuentas y cuentas (M15 §5.2)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CON-0007</td><td>RF-CON-007; M15 §5.2; PRO-O5-10</td><td>O5</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Crear, copiar, versionar y administrar varios planes de cuentas por tenant, identificados y versionados.</td><td>Se crea PC-OPER-01 en O5; en O8 se copia a PC-ALT-01 conservando estructura.</td></tr><tr><td>CP-CON-0008</td><td>RF-CON-008; M15 §5.2; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Propósito del plan: operativo, alternativo, simulación, regulatorio o externo.</td><td>Un plan alternativo no puede recibir asientos oficiales.</td></tr><tr><td>CP-CON-0009</td><td>RF-CON-009; M15 §5.2; PRO-O5-10</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Estados del plan: borrador, aprobado, operativo, alternativo, archivado; un único plan operativo por ejercicio.</td><td>Intentar marcar dos planes operativos para el mismo ejercicio se rechaza.</td></tr><tr><td>CP-CON-0010</td><td>RF-CON-010; M15 §5.2; PRO-O5-10</td><td>O5</td><td>Núcleo</td><td>migración</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Árbol jerárquico de cuentas con código, nombre, nivel, cuenta padre y máscara de código configurable por plan (ej. <code>1.1.01.01.001</code> o el formato de 11 dígitos de ProCoop 6+5 con prefijos de 5, 3 y 1).</td><td>El árbol se arma por <code>parentId</code>; la máscara solo valida el formato visible.</td></tr><tr><td>CP-CON-0011</td><td>RF-CON-011; M15 §5.2; PRO-O5-10</td><td>O5</td><td>Núcleo</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Cuenta imputable o agrupadora; solo las imputables reciben renglones.</td><td>Un renglón contra una agrupadora se rechaza.</td></tr><tr><td>CP-CON-0012</td><td>RF-CON-012; M15 §5.2; PRO-O5-10</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Naturaleza explícita de cada cuenta (activo, pasivo, patrimonio neto, ingresos, egresos, orden deudora, orden acreedora) y saldo normal, en lugar de prefijos.</td><td>El cierre de ejercicio y los estados usan <code>nature</code>, no el primer dígito.</td></tr><tr><td>CP-CON-0013</td><td>RF-CON-013; M15 §5.2; PRO-O5-10</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Rubro y subrubro contable por cuenta para la exposición en estados contables.</td><td>El ESP agrupa por rubro (ej. &quot;Créditos por servicios&quot;).</td></tr><tr><td>CP-CON-0014</td><td>RF-CON-014; M15 §5.2; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Atributo &quot;ajustable por inflación&quot; (partida no monetaria) por cuenta.</td><td>Solo las cuentas ajustables entran en la corrida de ajuste.</td></tr><tr><td>CP-CON-0015</td><td>RF-CON-015; M15 §5.2; PRO-O5-10</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Política de centro de costo por cuenta: prohibido, opcional u obligatorio; centros habilitados por cuenta; distribución por defecto de la cuenta.</td><td>Un renglón de una cuenta con centro obligatorio sin distribución se rechaza; un centro no habilitado para la cuenta se rechaza.</td></tr><tr><td>CP-CON-0016</td><td>RF-CON-016; M15 §5.2; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Subcuenta o código auxiliar visible y dígito verificador opcional.</td><td>La columna subcuenta se muestra si la configuración lo indica.</td></tr><tr><td>CP-CON-0017</td><td>RF-CON-017; M15 §5.2; PRO-O5-10</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Vigencia de la cuenta; inactivación sin borrado si tiene movimientos; borrado físico solo sin movimientos ni referencias.</td><td>Una cuenta con movimientos solo puede inactivarse.</td></tr><tr><td>CP-CON-0018</td><td>RF-CON-018; M15 §5.2; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Moneda de la cuenta (ARS por defecto; otra para bancos o deudas en moneda extranjera) con reexpresión a ARS.</td><td>Un renglón en USD guarda moneda, cotización e importe en ARS.</td></tr><tr><td>CP-CON-0019</td><td>RF-CON-019; M15 §5.2; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Mapeo de cada cuenta a líneas de las plantillas de estados contables (INAES/RT) y, cuando corresponda, a categorías INAES.</td><td>Ninguna cuenta imputable con saldo queda fuera del ESP o ER; se informa en el control previo.</td></tr><tr><td>CP-CON-0020</td><td>RF-CON-020; M15 §5.2; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Renumerar una cuenta (cambiar su código visible) conservando identidad, historial y referencias.</td><td>Tras renumerar, roles, reglas y movimientos siguen apuntando a la cuenta (por id) y el historial muestra código anterior y nuevo.</td></tr><tr><td>CP-CON-0021</td><td>RF-CON-021; M15 §5.2; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Unificar cuentas: fusionar una cuenta origen en una destino del mismo plan y naturaleza; las referencias de configuración pasan a la destino; los movimientos de períodos abiertos se reclasifican con asiento; los de períodos cerrados se…</td><td>Después de unificar, el mayor de la destino incluye los movimientos de la origen con marca de procedencia y la origen queda inactiva.</td></tr><tr><td>CP-CON-0022</td><td>RF-CON-022; M15 §5.2; PRO-O5-10</td><td>O5</td><td>Núcleo</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Visualizar el plan en árbol o lista, imprimir y exportar.</td><td>Exportación XLSX/PDF con código, nombre, naturaleza, imputable, ajustable, rubro.</td></tr><tr><td>CP-CON-0023</td><td>RF-CON-023; M15 §5.2; PRO-O5-10</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Importar plan de cuentas desde Excel con el asistente de importación y ofrecer un plan modelo para cooperativas de servicios públicos.</td><td>El asistente muestra errores (padre inexistente, código duplicado) antes de confirmar.</td></tr><tr><td>CP-CON-0024</td><td>RF-CON-024; M15 §5.2; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Reasignación masiva de cuentas y rubros: cambiar en bloque el rubro de productos, servicios, impuestos y conceptos de compra, o la cuenta de bancos, roles de cuenta, proveedores y tipos de factura; filtro &quot;sin asignar&quot;; agrupación…</td><td>Reasignar 50 proveedores a otra cuenta deja 50 registros de auditoría y no altera asientos ya registrados.</td></tr><tr><td>CP-CON-0025</td><td>RF-CON-025; M15 §5.2; PRO-O10-02</td><td>O10</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Cuentas de capital social por rubro de capital; un rubro de producto pertenece a un solo rubro de capitalización.</td><td>Asignar un rubro a dos rubros de capital se rechaza.</td></tr><tr><td>CP-CON-0026</td><td>RF-CON-026; M15 §5.2; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Cuentas de resultado para el cierre: por prefijo o rango de cuentas de resultado, la cuenta de resultados destino, con marca de ganancias/pérdidas; la regla de mayor especificidad (prefijo más largo) gana; si no hay, se usa el rol…</td><td>Un ejercicio con ingresos de agua refunde contra &quot;Resultado sección Agua&quot; si así se configuró.</td></tr></tbody></table><h3 id="_1-3-ejercicios-y-periodos-m15-§5-3" tabindex="-1">1.3 Ejercicios y períodos (M15 §5.3) <a class="header-anchor" href="#_1-3-ejercicios-y-periodos-m15-§5-3" aria-label="Permalink to &quot;1.3 Ejercicios y períodos (M15 §5.3)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CON-0027</td><td>RF-CON-027; M15 §5.3; PRO-O5-10</td><td>O5</td><td>Núcleo</td><td>migración</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>ABM de ejercicios: número, fecha desde, fecha hasta, estado; desde &lt; hasta; número único; sin solapamiento ni contención de otro ejercicio.</td><td>Un ejercicio que contiene por completo a otro se rechaza (corrige el defecto de ProCoop).</td></tr><tr><td>CP-CON-0028</td><td>RF-CON-028; M15 §5.3; PRO-O5-10</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Generación automática de períodos mensuales por ejercicio, incluidos ejercicios irregulares.</td><td>Un ejercicio 01-07-2026 a 30-06-2027 genera 12 períodos.</td></tr><tr><td>CP-CON-0029</td><td>RF-CON-029; M15 §5.3; PRO-O5-10</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Bloqueo por módulo dentro de cada período: comprobantes de venta, facturación, cobranza, compras, bancos, tesorería, financiaciones, viviendas, stock, sueldos, titulares, bienes de uso y contable, reemplazando las fechas de cierre P67…</td><td>Con cobranza bloqueada hasta 31-10-2026, un pago con fecha 30-10-2026 se rechaza con el mensaje de período cerrado.</td></tr><tr><td>CP-CON-0030</td><td>RF-CON-030; M15 §5.3; PRO-O5-10</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Servicio de guarda de período (<code>periodGuard</code>) consultado por todos los módulos antes de registrar o modificar una operación con fecha; responde permitido/rechazado y motivo.</td><td>Modificar una factura de un período contable cerrado se rechaza aunque facturación esté abierta.</td></tr><tr><td>CP-CON-0031</td><td>RF-CON-031; M15 §5.3; PRO-O5-10</td><td>O5</td><td>Núcleo</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Cierre mensual de período con lista de control: eventos pendientes de configuración = 0, asientos en borrador = 0, cajas cerradas, conciliaciones sin diferencias no explicadas, amortizaciones y provisiones registradas, ajuste por inflación…</td><td>El cierre no se habilita mientras haya un evento pendiente; el sistema lista los bloqueantes.</td></tr><tr><td>CP-CON-0032</td><td>RF-CON-032; M15 §5.3; PRO-O5-10</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Reapertura controlada de período: solicitud con motivo, aprobación (T11), plazo opcional de reapertura, auditoría y recierre.</td><td>La reapertura sin aprobación es imposible; queda constancia de quién, cuándo y por qué.</td></tr><tr><td>CP-CON-0033</td><td>RF-CON-033; M15 §5.3; PRO-O5-10</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Varios ejercicios abiertos a la vez (anterior en cierre y nuevo en curso).</td><td>Se registran asientos de enero del ejercicio nuevo mientras se ajusta diciembre del anterior.</td></tr><tr><td>CP-CON-0034</td><td>RF-CON-034; M15 §5.3; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Ejercicios irregulares (primer ejercicio, cambio de fecha de cierre por asamblea).</td><td>Se crea un ejercicio de 6 meses sin error.</td></tr></tbody></table><h3 id="_1-4-asientos-manuales-personalizados-e-importados-m15-§5-4" tabindex="-1">1.4 Asientos manuales, personalizados e importados (M15 §5.4) <a class="header-anchor" href="#_1-4-asientos-manuales-personalizados-e-importados-m15-§5-4" aria-label="Permalink to &quot;1.4 Asientos manuales, personalizados e importados (M15 §5.4)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CON-0035</td><td>RF-CON-035; M15 §5.4; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Alta de asiento manual: fecha, descripción, renglones (cuenta, debe, haber, observación), distribución por centro de costo por porcentaje o importe, adjuntos de respaldo y referencia opcional a documento.</td><td>Se graba un asiento con adjunto PDF y dos centros 60/40.</td></tr><tr><td>CP-CON-0036</td><td>RF-CON-036; M15 §5.4; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>migración</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Validaciones del asiento: al menos dos renglones, debe = haber exacto, cuentas imputables y vigentes, período y módulo contable abiertos, descripción obligatoria, centros según la política de la cuenta y distribución al 100 %.</td><td>Un asiento de un solo renglón se rechaza (ProCoop admite uno).</td></tr><tr><td>CP-CON-0037</td><td>RF-CON-037; M15 §5.4; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Estados del asiento: borrador, pendiente de aprobación, contabilizado, anulado, revertido.</td><td>Solo los contabilizados afectan mayores y saldos.</td></tr><tr><td>CP-CON-0038</td><td>RF-CON-038; M15 §5.4; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Aprobación de asientos manuales y de ajuste según tipo e importe, con registro de quién grabó, revisó y autorizó.</td><td>Un ajuste de ARS 500.000 con umbral ARS 100.000 queda pendiente hasta que otro usuario lo apruebe.</td></tr><tr><td>CP-CON-0039</td><td>RF-CON-039; M15 §5.4; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Numeración interna global e inmutable y número visible correlativo por ejercicio; si cambia la fecha a otro ejercicio, cambia el número visible; formato configurable (incluido prefijo de 4 dígitos + correlativo de 4).</td><td>El primer asiento del ejercicio 2027 es el 1 aunque existan miles de 2026.</td></tr><tr><td>CP-CON-0040</td><td>RF-CON-040; M15 §5.4; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Tipos de asiento: manual, automático, ajuste, apertura, refundición de resultados, patrimonial de cierre, ajuste por inflación, importado, reversión, distribución de excedentes, reclasificación.</td><td>Filtrar el diario por tipo devuelve solo los de ese tipo.</td></tr><tr><td>CP-CON-0041</td><td>RF-CON-041; M15 §5.4; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Plantillas de asiento personalizado y recurrente: cuentas o roles, lado, porcentaje o fórmula sobre un importe base, centro, periodicidad y reversión automática; incluye la plantilla de sueldos formato 3 (<code>SU_ASIENTOS</code>).</td><td>Una plantilla &quot;Devengamiento de seguros&quot; genera cada mes un asiento de ARS 12.000 en borrador.</td></tr><tr><td>CP-CON-0042</td><td>RF-CON-042; M15 §5.4; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Copiar asiento, revertir asiento (contraasiento con fecha elegida) y reversión automática el primer día del período siguiente (provisiones).</td><td>El contraasiento queda vinculado al original y ambos se ven en el mayor.</td></tr><tr><td>CP-CON-0043</td><td>RF-CON-043; M15 §5.4; PRO-O5-11</td><td>O5</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Compresión de renglones de igual cuenta, centro y lado en asientos resumen.</td><td>Un resumen con 300 renglones de la misma cuenta y centro se comprime en uno.</td></tr><tr><td>CP-CON-0044</td><td>RF-CON-044; M15 §5.4; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Documentación de origen y adjuntos por asiento, con expediente documental (T11).</td><td>El adjunto se descarga con URL firmada y queda auditado el acceso.</td></tr><tr><td>CP-CON-0045</td><td>RF-CON-045; M15 §5.4; PRO-O5-11</td><td>O5</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Importación de asientos desde Excel/CSV, con y sin centros de costo y en modalidad &quot;asiento único&quot;, con validación previa de cuentas, balance por asiento, ejercicio abierto, período no bloqueado y numeración por ejercicio.</td><td>Un archivo con un asiento desbalanceado no importa ninguno y muestra la fila en error.</td></tr><tr><td>CP-CON-0046</td><td>RF-CON-046; M15 §5.4; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Anulación masiva de asientos por filtros (rango, origen, lote, módulo), con permiso específico, excluyendo apertura y cierre, validando período abierto y no rubricado, y revirtiendo los efectos dependientes (amortizaciones).</td><td>Anular un lote de amortización notifica a STK y los acumulados de los bienes vuelven al valor previo.</td></tr><tr><td>CP-CON-0047</td><td>RF-CON-047; M15 §5.4; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Renumeración de asientos de un ejercicio por fecha, con apertura primero, cierre al final y luego orden de registro, desde un número inicial o continuando el último, solo para el rango no transcripto a libro rubricado.</td><td>Renumerar un rango ya impreso en hojas rubricadas se rechaza.</td></tr><tr><td>CP-CON-0048</td><td>RF-CON-048; M15 §5.4; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Consulta del diario con filtros por fecha de asiento o de registro, tipo, origen (automático/manual), módulo, estado, cuenta, centro, usuario, importe y documento; navegación al documento.</td><td>Desde un asiento resumen de cobranza se llega a cada recibo incluido.</td></tr><tr><td>CP-CON-0049</td><td>RF-CON-049; M15 §5.4; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Asientos en moneda extranjera: renglón con moneda, cotización e importe en ARS; diferencias de cambio por eventos de TES.</td><td>Un depósito en USD 100 a 1.000 se registra ARS 100.000 con moneda y cotización.</td></tr><tr><td>CP-CON-0050</td><td>RF-CON-050; M15 §5.4; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Auditoría de altas, modificaciones, aprobaciones, anulaciones y reversiones con antes y después.</td><td>La auditoría muestra el renglón modificado de un borrador con usuario y hora.</td></tr></tbody></table><h3 id="_1-5-motor-de-asientos-automaticos-m15-§5-5" tabindex="-1">1.5 Motor de asientos automáticos (M15 §5.5) <a class="header-anchor" href="#_1-5-motor-de-asientos-automaticos-m15-§5-5" aria-label="Permalink to &quot;1.5 Motor de asientos automáticos (M15 §5.5)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CON-0051</td><td>RF-CON-051; M15 §5.5; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>integración</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Recepción de los eventos económicos de todos los módulos vía outbox en una bandeja (<code>accountingEvents</code>), idempotente por identificador del evento de origen.</td><td>Recibir dos veces el mismo <code>fac.invoice.issued</code> crea un solo evento y un solo asiento.</td></tr><tr><td>CP-CON-0052</td><td>RF-CON-052; M15 §5.5; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Contrato del evento económico: tipo, documento de origen, fecha contable, moneda, renglones económicos con <strong>rol de importe</strong> (neto, descuento, IVA por alícuota y condición, percepción, retención, impuesto interno, tasa de terceros…</td><td>Un evento sin rol de importe válido se rechaza con error de contrato y alerta técnica.</td></tr><tr><td>CP-CON-0053</td><td>RF-CON-053; M15 §5.5; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Reglas de imputación configurables por tipo de evento y rol de importe con condiciones por cualquier dimensión, vigencia, versión y prioridad; cuenta y, opcionalmente, centro o modelo de distribución.</td><td>Una regla &quot;Ingresos Internet zona Norte&quot; vigente desde 01-11-2026 se aplica solo a eventos con esa fecha o posterior.</td></tr><tr><td>CP-CON-0054</td><td>RF-CON-054; M15 §5.5; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Resolución en cascada: cuenta asignada en la entidad (proveedor, banco, alícuota, rubro, tipo de factura, grupo contable, concepto de sueldo, sindicato, obra, tipo de retención, tipo de valor, categoría de movimiento) → regla con más…</td><td>En el renglón se ve &quot;regla R-104 (3 coincidencias: servicio, zona, rubro)&quot;.</td></tr><tr><td>CP-CON-0055</td><td>RF-CON-055; M15 §5.5; PRO-O5-11</td><td>O5</td><td>Estándar</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Simulador de reglas: con un evento de ejemplo, mostrar las cuentas y centros resultantes y la ruta de resolución, sin registrar nada.</td><td>El contador prueba un cobro con tarjeta y ve las cuentas sin generar asiento.</td></tr><tr><td>CP-CON-0056</td><td>RF-CON-056; M15 §5.5; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Asiento por operación o resumen diario/por rango por módulo, con agrupación configurable por cuenta, centro y dimensiones (grupo contable, tipo de comprobante, zona, rubro, servicio).</td><td>El resumen de ventas del 03-11-2026 agrupa por servicio y concepto.</td></tr><tr><td>CP-CON-0057</td><td>RF-CON-057; M15 §5.5; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Vínculo bidireccional documento ↔ evento ↔ asiento ↔ renglón.</td><td>Desde la factura se abre su asiento; desde el renglón resumen, las facturas que lo componen.</td></tr><tr><td>CP-CON-0058</td><td>RF-CON-058; M15 §5.5; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Reversión automática al anular el documento o evento de origen: contraasiento vinculado en el período del origen si está abierto, o en el período abierto actual con referencia si está cerrado.</td><td>Anular una NC del 05-11 genera el contraasiento del 05-11.</td></tr><tr><td>CP-CON-0059</td><td>RF-CON-059; M15 §5.5; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Evento sin cuenta resuelta: queda &quot;pendiente de configuración&quot;, genera alerta y bloquea el cierre del período, sin bloquear la operación de origen.</td><td>Cobrar en un medio nuevo sin cuenta no impide el cobro; el evento aparece en la bandeja de pendientes.</td></tr><tr><td>CP-CON-0060</td><td>RF-CON-060; M15 §5.5; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Reprocesar eventos pendientes o con error luego de corregir la configuración, de a uno o masivamente.</td><td>Tras asignar la cuenta, el reproceso contabiliza los 35 eventos pendientes.</td></tr><tr><td>CP-CON-0061</td><td>RF-CON-061; M15 §5.5; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Tolerancia de redondeo configurable en asientos automáticos: la diferencia dentro de la tolerancia va al rol de redondeo del módulo; fuera de ella, el evento queda en error.</td><td>Una diferencia de ARS 0,01 en un resumen de cobranza va a &quot;Redondeo cierre de caja&quot;.</td></tr><tr><td>CP-CON-0062</td><td>RF-CON-062; M15 §5.5; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Lote de contabilización (reemplazo del &quot;Cierre automático&quot;): rango de fechas, módulos a incluir (ventas, pagos de otros períodos, cobranzas, tesorería, bancos, financiaciones, compras, stock, capital, sueldos, fabricación, bienes de uso…</td><td>Correr el lote dos veces para el mismo día no crea asientos nuevos: informa &quot;0 eventos pendientes&quot;.</td></tr><tr><td>CP-CON-0063</td><td>RF-CON-063; M15 §5.5; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Previsualización del lote (borrador) con mayor y composición de ventas, stock y ajustes; confirmación o descarte; si mientras tanto se registraron otros asientos, la numeración se recalcula al confirmar.</td><td>El contador descarta un lote y los eventos vuelven a pendientes.</td></tr><tr><td>CP-CON-0064</td><td>RF-CON-064; M15 §5.5; PRO-O5-11</td><td>O5</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Aviso de cajas abiertas en el rango y opción de exigir cajas cerradas antes de contabilizar cobranzas en resumen.</td><td>Con la opción activa, el lote del día con una caja abierta se detiene y la lista.</td></tr><tr><td>CP-CON-0065</td><td>RF-CON-065; M15 §5.5; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Matriz de eventos económicos de todos los módulos con su asiento tipo (§9.1).</td><td>Cada evento de la matriz tiene regla por defecto en el plan modelo.</td></tr><tr><td>CP-CON-0066</td><td>RF-CON-066; M15 §5.5; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Facturación: contabilizar por concepto, servicio, rubro, zona, tipo de factura y grupo contable, con modalidad de deudores configurable (por tipo de factura o por concepto, con o sin IVA separado), opción de no usar grupos contables y…</td><td>El asiento de facturación de Agua acredita Ingresos Agua y debita Créditos por servicios – Agua.</td></tr><tr><td>CP-CON-0067</td><td>RF-CON-067; M15 §5.5; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Cobranza: contabilizar por medio de pago, caja, grupo contable, ente y banco, con cuenta transitoria de acreditaciones pendientes y registración separada de comisiones y retenciones sufridas.</td><td>El cobro digital de ARS 8.000 acreditado neto 7.840 con comisión 160 cuadra (CU-22).</td></tr><tr><td>CP-CON-0068</td><td>RF-CON-068; M15 §5.5; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Compras: distribución por centro de costo por ítem, IVA computable por centro (porcentaje de IVA compras de la sección), IVA no tomado como gasto, ítems pendientes de recepción, remitos, obras y retenciones.</td><td>Una factura de ARS 121.000 (neto 100.000) imputada 50 % a una sección con 60 % de IVA computable y 50 % a una sección con 100 % registra IVA CF 16.800 y gasto IVA 4.200 (ver CU-CON-05).</td></tr><tr><td>CP-CON-0069</td><td>RF-CON-069; M15 §5.5; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Pagos a proveedores: medios de pago (efectivo de caja de pagos, valores de terceros, cheques propios, transferencias, VEP, transferencias diferidas), descuentos obtenidos y cuentas puente de pago con devengamiento.</td><td>Una OP con cheque propio diferido acredita &quot;Cheques diferidos a pagar&quot; del banco, no el banco.</td></tr><tr><td>CP-CON-0070</td><td>RF-CON-070; M15 §5.5; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Tesorería y bancos: cambio de valores, transferencias entre bancos, ingresos y egresos excepcionales por categoría, rechazo y recupero de valores, quebrantos, presentación y cobro de tarjetas con comisiones, presentación de retenciones…</td><td>Un débito bancario sin categoría contable va a &quot;Débitos bancarios sin subcategoría&quot;.</td></tr><tr><td>CP-CON-0071</td><td>RF-CON-071; M15 §5.5; PRO-O3-03</td><td>O3</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Stock: materiales en OT y OM con horas de participantes valuadas, conciliaciones, vales (incluidos los de vivienda con obra por defecto), costo de mercadería vendida, entregas y retiros de comodato, revaluación y altas en orden, con el…</td><td>La instalación de un módem en comodato registra el activo en comodato sin gasto (CU-OPE-01).</td></tr><tr><td>CP-CON-0072</td><td>RF-CON-072; M15 §5.5; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Bienes de uso: alta, amortización por centro de costo del bien, mejoras, disminuciones, bajas, ventas y ajuste por inflación con cuentas de revalúo separadas y valores históricos.</td><td>La amortización mensual de un camión 70 % Distribución / 30 % Administración se registra con esa distribución.</td></tr><tr><td>CP-CON-0073</td><td>RF-CON-073; M15 §5.5; PRO-O9-07</td><td>O9</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Sueldos: devengamiento por concepto, centro de costo, servicio y plan, con formatos recibos + contribuciones, por sindicato o personalizado; pago; anticipos; descuento de deuda de servicios.</td><td>El asiento de octubre 2026 distribuye costo laboral en Distribución, Administración e Internet (CU-104).</td></tr><tr><td>CP-CON-0074</td><td>RF-CON-074; M15 §5.5; PRO-O6-07</td><td>O6</td><td>Estándar</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Mora y financiación: intereses y recargos facturados, convenios y refinanciaciones con intereses e IVA a devengar por cuota, previsión y castigo de incobrables, prescripción de deuda, recuperos.</td><td>Un convenio de ARS 30.000 + 3.000 de interés reconoce el interés como ganado solo al vencer cada cuota.</td></tr><tr><td>CP-CON-0075</td><td>RF-CON-075; M15 §5.5; PRO-O10-02</td><td>O10</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Capital social: suscripción al facturar o en la afiliación, integración en el pago, capital a devolver, reembolso, rescate por socios incobrables, transferencias, capitalización de retornos y distribución de excedentes, con M17.</td><td>Cobrar ARS 1.000 de cuota social con la factura no aumenta ingresos por servicios. La suscripción, la integración y su conciliación se adelantan a O5 por RF-CON-150, RF-CON-151 y RF-CON-098; el resto queda en O10 por RF-CON-161 (HUECO-CAP-01).</td></tr><tr><td>CP-CON-0076</td><td>RF-CON-076; M15 §5.5; PRO-O10-02</td><td>O10</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Fabricación: productos en proceso con costo de componentes PEPS y productos terminados por proporción de cantidades.</td><td>Al finalizar una orden, &quot;Productos en proceso&quot; queda en cero para esa orden.</td></tr><tr><td>CP-CON-0077</td><td>RF-CON-077; M15 §5.5; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Fiscal: liquidación de IVA (compensación débito/crédito, saldo a pagar o a favor), pago de impuestos, retenciones y percepciones a organismos, rendición de tasas de terceros cobradas.</td><td>El pago de ARS 2.000 de retenciones cancela el pasivo (CU-FIS-01).</td></tr><tr><td>CP-CON-0078</td><td>RF-CON-078; M15 §5.5; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Ventas de productos y ventas financiadas con costo de mercadería vendida e intereses a devengar.</td><td>Una venta en 6 cuotas reconoce intereses mes a mes.</td></tr><tr><td>CP-CON-0079</td><td>RF-CON-079; M15 §5.5; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Tesorería financiera: préstamos recibidos, plazos fijos, intereses y gastos financieros, diferencias de cambio.</td><td>Un plazo fijo registra el interés devengado al vencimiento.</td></tr><tr><td>CP-CON-0080</td><td>RF-CON-080; M15 §5.5; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Asientos de ajuste de cierre como plantillas con reversión: provisión de SAC y vacaciones, previsión de incobrables, ingresos devengados no facturados, gastos devengados no facturados.</td><td>La provisión de ingresos devengados no facturados del 31-12 se revierte el 01-01.</td></tr></tbody></table><h3 id="_1-6-centros-de-costo-secciones-m15-§5-6" tabindex="-1">1.6 Centros de costo (secciones) (M15 §5.6) <a class="header-anchor" href="#_1-6-centros-de-costo-secciones-m15-§5-6" aria-label="Permalink to &quot;1.6 Centros de costo (secciones) (M15 §5.6)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CON-0081</td><td>RF-CON-081; M15 §5.6; PRO-O5-10</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>ABM de centros de costo propios del tenant: código, nombre, jerarquía opcional, porcentaje de IVA compras computable, vigencia y relación opcional con servicio, área, sucursal o zona, sin imponer equivalencia con servicios.</td><td>Se crean CC-AG, CC-INT, CC-ADM; CC-ADM no se asocia a ningún servicio.</td></tr><tr><td>CP-CON-0082</td><td>RF-CON-082; M15 §5.6; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Grupos de centros (un centro puede integrar varios grupos) para informes.</td><td>El grupo &quot;Servicios técnicos&quot; suma Agua e Internet.</td></tr><tr><td>CP-CON-0083</td><td>RF-CON-083; M15 §5.6; PRO-O5-10</td><td>O5</td><td>Núcleo</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Reglas de asignación por defecto por tipo de operación (ingresos/facturación, compras, ajuste por inflación, asiento manual, costo de mercadería vendida, sección por defecto de cuenta) y tipo de elemento (servicio, producto, concepto…</td><td>El concepto &quot;Abono Internet&quot; se asigna 100 % a CC-INT sin carga manual.</td></tr><tr><td>CP-CON-0084</td><td>RF-CON-084; M15 §5.6; PRO-O5-10</td><td>O5</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Modelos de distribución reutilizables (plantillas) seleccionables al asignar.</td><td>El modelo &quot;DIST-DEMO-25-75&quot; se aplica a varias cuentas de gastos comunes.</td></tr><tr><td>CP-CON-0085</td><td>RF-CON-085; M15 §5.6; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Distribuciones propias de bienes de uso, empleados, categorías de incidentes, grupos de obras e ítems de compra, recibidas en los eventos de cada módulo.</td><td>El evento de amortización trae la distribución del bien y el asiento la respeta.</td></tr><tr><td>CP-CON-0086</td><td>RF-CON-086; M15 §5.6; PRO-O5-10</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Al contabilizar, cualquier renglón sin centro de una cuenta que lo admite toma la distribución por defecto de su cuenta.</td><td>Un gasto sin centro de una cuenta con defecto 100 % CC-ADM queda en CC-ADM.</td></tr><tr><td>CP-CON-0087</td><td>RF-CON-087; M15 §5.6; PRO-O5-10</td><td>O5</td><td>Núcleo</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Redondeo de distribución: la suma de importes distribuidos iguala el importe del renglón; el último centro absorbe la diferencia; decimales de porcentaje configurables.</td><td>ARS 100 en tres partes iguales da 33,33 / 33,33 / 33,34.</td></tr><tr><td>CP-CON-0088</td><td>RF-CON-088; M15 §5.6; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Distribución analítica de costos comunes con reglas versionadas (porcentaje fijo o driver: cantidad de suministros activos, kWh, m³, horas, metros de red, ingresos), sin duplicar el gasto; importes no asignados identificados.</td><td>Con DIST-DEMO-25-75 los ARS 4.000 comunes se reparten 1.000/3.000 y el gasto total sigue en 4.000.</td></tr><tr><td>CP-CON-0089</td><td>RF-CON-089; M15 §5.6; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Reclasificación contable opcional entre centros (asiento neutro de reclasificación) cuando la cooperativa decide exponer la distribución en libros.</td><td>El asiento de reclasificación tiene efecto neto cero por cuenta.</td></tr><tr><td>CP-CON-0090</td><td>RF-CON-090; M15 §5.6; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Estado de resultados por sección/servicio con ingresos directos, costos directos, comunes distribuidos y resultado.</td><td>La tabla de CU-CON-01 se reproduce: Agua 6.000, Internet 10.000, total 16.000.</td></tr><tr><td>CP-CON-0091</td><td>RF-CON-091; M15 §5.6; PRO-O5-10</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Activación de centros de costo general o solo para sueldos.</td><td>Con &quot;solo sueldos&quot;, las compras no exigen centro.</td></tr></tbody></table><h3 id="_1-7-cuentas-corrientes-por-servicio-y-conciliaciones-m15-§5-7" tabindex="-1">1.7 Cuentas corrientes por servicio y conciliaciones (M15 §5.7) <a class="header-anchor" href="#_1-7-cuentas-corrientes-por-servicio-y-conciliaciones-m15-§5-7" aria-label="Permalink to &quot;1.7 Cuentas corrientes por servicio y conciliaciones (M15 §5.7)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CON-0092</td><td>RF-CON-092; M15 §5.7; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Cuentas de control de créditos por servicios con dimensión servicio obligatoria (subcuenta o dimensión) para explicar el saldo por servicio.</td><td>El saldo contable de Créditos por servicios – Agua iguala la suma de saldos Agua del auxiliar.</td></tr><tr><td>CP-CON-0093</td><td>RF-CON-093; M15 §5.7; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Conciliación del auxiliar de asociados (COB) contra la cuenta de control, por servicio y total, a una fecha de corte, con diferencias clasificadas por corte, estado o clasificación.</td><td>En CU-CON-01 el auxiliar (33.000) y la cuenta de control (33.000) coinciden.</td></tr><tr><td>CP-CON-0094</td><td>RF-CON-094; M15 §5.7; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Conciliación caja/bancos/valores (TES) contra cuentas, distinguiendo comisiones y retenciones.</td><td>Una comisión no registrada aparece como diferencia &quot;clasificación&quot;.</td></tr><tr><td>CP-CON-0095</td><td>RF-CON-095; M15 §5.7; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Conciliación proveedores (CMP) contra cuenta de proveedores y anticipos.</td><td>Un anticipo pendiente se explica en la conciliación.</td></tr><tr><td>CP-CON-0096</td><td>RF-CON-096; M15 §5.7; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Conciliación fiscal: IVA débito/crédito contra libros IVA (FIS), retenciones y percepciones a depositar contra declaraciones.</td><td>El IVA DF contable de octubre coincide con el libro IVA ventas.</td></tr><tr><td>CP-CON-0097</td><td>RF-CON-097; M15 §5.7; PRO-O8-10</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Conciliación de stock valorizado y bienes de uso (STK) contra sus cuentas.</td><td>Existencias valorizadas = saldo de Bienes de cambio al corte.</td></tr><tr><td>CP-CON-0098</td><td>RF-CON-098; M15 §5.7; PRO-O5-12</td><td>O5</td><td>Estándar</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Conciliación de capital (M17) contra cuentas de capital. Se adelanta a O5 junto con la contabilización del capital mínimo (DEC-019); durante la convivencia concilia el plan no oficial (DEC-068, DEC-069) (HUECO-CAP-01).</td><td>Capital suscripto del auxiliar = cuenta contable.</td></tr><tr><td>CP-CON-0099</td><td>RF-CON-099; M15 §5.7; PRO-O9-07</td><td>O9</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Conciliación de sueldos a pagar y cargas sociales (SUE) contra cuentas.</td><td>El neto a pagar de la liquidación iguala la cuenta antes del pago.</td></tr><tr><td>CP-CON-0100</td><td>RF-CON-100; M15 §5.7; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Consulta contable de la cuenta corriente por asociado y servicio, vista unificada y detallada, con navegación al auxiliar de COB, sin duplicarlo.</td><td>La vista unificada muestra ARS 33.000 con el detalle Agua 8.000 e Internet 25.000.</td></tr><tr><td>CP-CON-0101</td><td>RF-CON-101; M15 §5.7; PRO-O5-11</td><td>O5</td><td>Estándar</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Informe de anticipos y saldos a favor de clientes a una fecha, con deuda reconstruida y prorrateo por ítem.</td><td>Al 31-10-2026 lista ARS 2.000 a favor del ESC-01 y coincide con la cuenta de anticipos.</td></tr><tr><td>CP-CON-0102</td><td>RF-CON-102; M15 §5.7; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Justificación de cada diferencia de conciliación con responsable, causa y, si corresponde, ajuste trazable autorizado.</td><td>Ningún ajuste de conciliación carece de operación, causa, autor y contrapartida.</td></tr></tbody></table><h3 id="_1-8-multiples-planes-equivalencias-y-simulaciones-m15-§5-8" tabindex="-1">1.8 Múltiples planes, equivalencias y simulaciones (M15 §5.8) <a class="header-anchor" href="#_1-8-multiples-planes-equivalencias-y-simulaciones-m15-§5-8" aria-label="Permalink to &quot;1.8 Múltiples planes, equivalencias y simulaciones (M15 §5.8)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CON-0103</td><td>RF-CON-103; M15 §5.8; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Equivalencias de cuentas entre planes (1:1, 1:N con porcentajes que suman 100 %, N:1), con vigencia y validación de completitud.</td><td>Una equivalencia 1:N al 60/40 no duplica importes.</td></tr><tr><td>CP-CON-0104</td><td>RF-CON-104; M15 §5.8; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Proyección automática de los asientos oficiales a planes alternativos y regulatorios mediante equivalencias, como representación sin libros propios.</td><td>El balance en PC-ALT-01 suma igual que en PC-OPER-01.</td></tr><tr><td>CP-CON-0105</td><td>RF-CON-105; M15 §5.8; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Detección de cuentas sin equivalencia, asignaciones ambiguas y asientos desequilibrados antes de aceptar resultados.</td><td>Sin mapeo completo, el escenario queda &quot;no comparable&quot;.</td></tr><tr><td>CP-CON-0106</td><td>RF-CON-106; M15 §5.8; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Escenarios de simulación con plan elegido, período, universo de operaciones, supuestos (cambio de estructura, reparto de comunes, variación tarifaria, variación de costos) y fecha de corte.</td><td>SIM-CON-001 reparte 50/50 y muestra Agua 5.000 e Internet 11.000.</td></tr><tr><td>CP-CON-0107</td><td>RF-CON-107; M15 §5.8; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Copiar una base de simulación para comparar hipótesis identificables y repetibles.</td><td>Re-ejecutar el mismo escenario con el mismo corte da el mismo resultado.</td></tr><tr><td>CP-CON-0108</td><td>RF-CON-108; M15 §5.8; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Comparar escenarios entre sí y contra el real con el mismo universo, distinguiendo diferencias de clasificación de cambios de valores.</td><td>La comparación +10 % tarifa muestra 41.800 como diferencia de valores, no de clasificación.</td></tr><tr><td>CP-CON-0109</td><td>RF-CON-109; M15 §5.8; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>seguridad</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Aislamiento total: una simulación no emite facturas, no genera deuda, no mueve fondos, no envía órdenes a terceros ni contabiliza oficialmente; sus movimientos viven en colecciones separadas.</td><td>Ninguna consulta del mayor oficial lee <code>simulatedJournalLines</code>.</td></tr><tr><td>CP-CON-0110</td><td>RF-CON-110; M15 §5.8; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Exportar resultados de simulación identificados como tales en cada hoja y archivo.</td><td>El XLSX lleva la marca &quot;SIMULACIÓN SIM-CON-001&quot; en encabezado y nombre.</td></tr><tr><td>CP-CON-0111</td><td>RF-CON-111; M15 §5.8; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Promoción de un plan o configuración aprobada (alternativo → operativo) solo por acción explícita, con aprobación, nueva vigencia (inicio de ejercicio), traspaso de saldos de apertura por equivalencias y auditoría; nunca conversión de…</td><td>La promoción crea el asiento de apertura en el plan nuevo y deja el anterior archivado.</td></tr></tbody></table><h3 id="_1-9-mayor-balances-estados-contables-e-informes-m15-§5-9" tabindex="-1">1.9 Mayor, balances, estados contables e informes (M15 §5.9) <a class="header-anchor" href="#_1-9-mayor-balances-estados-contables-e-informes-m15-§5-9" aria-label="Permalink to &quot;1.9 Mayor, balances, estados contables e informes (M15 §5.9)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CON-0112</td><td>RF-CON-112; M15 §5.9; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Libro diario en pantalla e impresión, con renumeración solo de impresión desde un número N y detalle por sección con porcentaje.</td><td>Imprimir desde 1.001 no cambia la numeración guardada.</td></tr><tr><td>CP-CON-0113</td><td>RF-CON-113; M15 §5.9; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Libro diario rubricado (apertura primero), libro inventario y balances, y transcripción sobre hojas rubricadas.</td><td>El folio continúa desde la última hoja usada.</td></tr><tr><td>CP-CON-0114</td><td>RF-CON-114; M15 §5.9; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Mayor de una cuenta o de varias: rango, saldo anterior, movimientos, saldo acumulado, centro, ver asiento y navegar al documento.</td><td>Desde un movimiento del mayor se abre el asiento y desde allí la factura.</td></tr><tr><td>CP-CON-0115</td><td>RF-CON-115; M15 §5.9; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Sumas y saldos / balance de comprobación por período, por meses o acumulado, por nivel, con detalle por sección y acceso al mayor.</td><td>Total debe = total haber; diferencia cero siempre.</td></tr><tr><td>CP-CON-0116</td><td>RF-CON-116; M15 §5.9; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Transacciones por cuenta.</td><td>Lista renglones con documento de origen.</td></tr><tr><td>CP-CON-0117</td><td>RF-CON-117; M15 §5.9; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Balance diario por niveles, balance general, balance entre períodos (dos subperíodos con padres acumulados) y saldos de cuentas por nivel.</td><td>El balance entre períodos muestra 1er y 2do semestre y el total.</td></tr><tr><td>CP-CON-0118</td><td>RF-CON-118; M15 §5.9; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Distribución por secciones y rubros; gastos e ingresos por sección y por grupos de secciones, mensual hasta 12 meses, exportable a Excel.</td><td>El informe usa la naturaleza de la cuenta, no los dígitos &quot;4&quot; y &quot;5&quot;.</td></tr><tr><td>CP-CON-0119</td><td>RF-CON-119; M15 §5.9; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Estados contables en formato INAES/normas profesionales (ESP, ER, EEPN, EFE, notas y anexos: bienes de uso, previsiones, gastos por función y sección, inversiones, resultados por sección), comparativos con el ejercicio anterior, con…</td><td>Los estados del ejercicio 2026 se generan desde los saldos y cuadran con sumas y saldos.</td></tr><tr><td>CP-CON-0120</td><td>RF-CON-120; M15 §5.9; PRO-O10-02</td><td>O10</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Cuadro de distribución de excedentes propuesto a la asamblea y resultado por operaciones con asociados y no asociados.</td><td>El cuadro parte del excedente del ER y suma 100 %.</td></tr><tr><td>CP-CON-0121</td><td>RF-CON-121; M15 §5.9; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Control previo a balances: cuentas no imputables con saldo (hasta todas, no solo 20), cuentas sin naturaleza o sin línea de estado, eventos pendientes, borradores y diferencias de conciliación.</td><td>El control lista cada problema con enlace.</td></tr><tr><td>CP-CON-0122</td><td>RF-CON-122; M15 §5.9; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Cuadro de bienes de uso (origen + mejoras − disminuciones) y cuadro de amortizaciones (apertura, ejercicio, cierre) para el anexo de estados contables, con datos de STK conciliados.</td><td>El cuadro coincide con las cuentas de bienes de uso.</td></tr><tr><td>CP-CON-0123</td><td>RF-CON-123; M15 §5.9; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Informes de gestión contable: resultado y costo por servicio y centro, evolución mensual, ejecución presupuestaria; los indicadores de gestión no contables se definen en T10 con el contrato semántico de §15.</td><td>Cada indicador indica fórmula, universo y corte.</td></tr><tr><td>CP-CON-0124</td><td>RF-CON-124; M15 §5.9; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Todo reporte declara fecha de corte, universo, estados incluidos y separación real/simulado.</td><td>El encabezado de cada reporte muestra corte y universo.</td></tr><tr><td>CP-CON-0125</td><td>RF-CON-125; M15 §5.9; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Trazabilidad informe → asiento → documento → operación de origen y viceversa.</td><td>Desde la línea &quot;Ingresos Internet&quot; del ER se llega a las facturas.</td></tr><tr><td>CP-CON-0126</td><td>RF-CON-126; M15 §5.9; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>seguridad</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Exportación XLSX, CSV y PDF de todos los reportes, según permiso.</td><td>Sin <code>con.reportes.exportar</code> el botón no aparece y la API responde 403.</td></tr></tbody></table><h3 id="_1-10-ajuste-por-inflacion-m15-§5-10" tabindex="-1">1.10 Ajuste por inflación (M15 §5.10) <a class="header-anchor" href="#_1-10-ajuste-por-inflacion-m15-§5-10" aria-label="Permalink to &quot;1.10 Ajuste por inflación (M15 §5.10)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CON-0127</td><td>RF-CON-127; M15 §5.10; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Tablas de índices (por ejemplo IPC/FACPCE) con valores mensuales; carga manual, importación y actualización.</td><td>Se importa la serie 2025–2026 y se edita un mes.</td></tr><tr><td>CP-CON-0128</td><td>RF-CON-128; M15 §5.10; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Ajuste por inflación contable de las cuentas ajustables por coeficiente (índice de cierre / índice del mes de origen de cada partida), contra RECPAM, con previsualización y distribución a centros.</td><td>Una partida de ARS 100.000 de enero con coeficiente 1,25 se ajusta en ARS 25.000.</td></tr><tr><td>CP-CON-0129</td><td>RF-CON-129; M15 §5.10; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Ajuste de bienes de uso y amortizaciones con cuentas de revalúo separadas y valores históricos (cálculo en STK con índices de CON).</td><td>El asiento separa &quot;Bienes de uso – ajuste&quot; de &quot;valor de origen&quot; si la opción está activa.</td></tr><tr><td>CP-CON-0130</td><td>RF-CON-130; M15 §5.10; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Contabilización de la revaluación de stock por índice del rubro calculada por STK.</td><td>La revaluación genera el asiento contra la cuenta configurada.</td></tr><tr><td>CP-CON-0131</td><td>RF-CON-131; M15 §5.10; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Si falta un índice del rango, la corrida no se ejecuta y lista los meses faltantes.</td><td>Falta marzo: la corrida se detiene con &quot;Falta índice 03-2026&quot;.</td></tr></tbody></table><h3 id="_1-11-cierre-y-reapertura-de-ejercicio-distribucion-de-excedentes-m15-§5-11" tabindex="-1">1.11 Cierre y reapertura de ejercicio, distribución de excedentes (M15 §5.11) <a class="header-anchor" href="#_1-11-cierre-y-reapertura-de-ejercicio-distribucion-de-excedentes-m15-§5-11" aria-label="Permalink to &quot;1.11 Cierre y reapertura de ejercicio, distribución de excedentes (M15 §5.11)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CON-0132</td><td>RF-CON-132; M15 §5.11; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Cierre de ejercicio: validar que no existan asientos de cierre previos ni pendientes; asiento de refundición de resultados contra cuentas de resultado por prefijo o rol &quot;asignación de resultados&quot;; asiento patrimonial de cierre; asiento de…</td><td>Tras cerrar 2026, todas las cuentas de resultado quedan en cero y la apertura 2027 iguala el patrimonial invertido.</td></tr><tr><td>CP-CON-0133</td><td>RF-CON-133; M15 §5.11; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Reapertura de ejercicio controlada: solicitud, doble aprobación, reversión (no borrado) de los tres asientos, auditoría y nuevo cierre.</td><td>La reapertura deja visibles los asientos de cierre originales y sus reversiones.</td></tr><tr><td>CP-CON-0134</td><td>RF-CON-134; M15 §5.11; PRO-O10-02</td><td>O10</td><td>Estándar</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Asiento de distribución de excedentes según resolución de asamblea (reservas, fondos, interés a cuotas sociales, retornos, capitalización) con evento de M17.</td><td>El asiento usa la resolución de asamblea como documento de origen.</td></tr><tr><td>CP-CON-0135</td><td>RF-CON-135; M15 §5.11; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Tratamiento configurable de cuentas de orden en el cierre (incluir en cierre y apertura o exigir saldo cero).</td><td>Con la opción recomendada, las cuentas de orden se trasladan al ejercicio nuevo.</td></tr></tbody></table><h3 id="_1-12-libros-rubricados-m15-§5-12" tabindex="-1">1.12 Libros rubricados (M15 §5.12) <a class="header-anchor" href="#_1-12-libros-rubricados-m15-§5-12" aria-label="Permalink to &quot;1.12 Libros rubricados (M15 §5.12)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CON-0136</td><td>RF-CON-136; M15 §5.12; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Registro de libros rubricados (diario, inventario y balances): organismo, número de rúbrica, fecha, hojas desde-hasta, líneas por hoja, última hoja usada; impresión de hojas numeradas para rubricar.</td><td>Se imprimen las hojas 1 a 200 con encabezado y numeración.</td></tr><tr><td>CP-CON-0137</td><td>RF-CON-137; M15 §5.12; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Transcripción del diario sobre hojas rubricadas con continuidad de folio; los asientos transcriptos quedan bloqueados para anular, renumerar o modificar.</td><td>Un asiento transcripto solo admite contraasiento.</td></tr><tr><td>CP-CON-0138</td><td>RF-CON-138; M15 §5.12; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Libros en formato digital con huella (hash) e índice cuando el organismo de registro lo admita.</td><td>El archivo exportado incluye hash SHA-256 verificable.</td></tr></tbody></table><h3 id="_1-13-sistema-contable-externo-m15-§5-13" tabindex="-1">1.13 Sistema contable externo (M15 §5.13) <a class="header-anchor" href="#_1-13-sistema-contable-externo-m15-§5-13" aria-label="Permalink to &quot;1.13 Sistema contable externo (M15 §5.13)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CON-0139</td><td>RF-CON-139; M15 §5.13; PRO-O5-11</td><td>O5</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Mapeo de operaciones y cuentas propias a cuentas y rubros de un sistema contable externo (operación, cuenta, rubro, observación).</td><td>Cada cuenta del plan operativo tiene correspondencia o aparece como faltante.</td></tr><tr><td>CP-CON-0140</td><td>RF-CON-140; M15 §5.13; PRO-O5-11</td><td>O5</td><td>Estándar</td><td>integración</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Exportación de asientos y mayores al sistema externo con layouts configurables (CSV, TXT posicional, XLSX) mediante el exportador de T06, incremental, idempotente y con marca de exportado.</td><td>Reexportar el mismo rango sin cambios no duplica asientos en el destino.</td></tr><tr><td>CP-CON-0141</td><td>RF-CON-141; M15 §5.13; PRO-O5-11</td><td>O5</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Importación de asientos del sistema externo (contabilidad llevada fuera durante el paralelo) con validaciones y marca de origen.</td><td>Los asientos importados se identifican como origen &quot;importado – sistema X&quot;.</td></tr><tr><td>CP-CON-0142</td><td>RF-CON-142; M15 §5.13; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Provisión de saldos y mapeos contables para exportaciones a reguladores y organismos (OCEBA con mapeo FEDECOBA/SUBCUENTA, SilarPib, archivos DGR), cuyos layouts y envío pertenecen a M06 FIS / T06.</td><td>FIS obtiene los saldos por cuenta mapeada desde la API de CON.</td></tr></tbody></table><h3 id="_1-14-presupuestos-y-compromisos-m15-§5-14" tabindex="-1">1.14 Presupuestos y compromisos (M15 §5.14) <a class="header-anchor" href="#_1-14-presupuestos-y-compromisos-m15-§5-14" aria-label="Permalink to &quot;1.14 Presupuestos y compromisos (M15 §5.14)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CON-0143</td><td>RF-CON-143; M15 §5.14; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Presupuesto económico por ejercicio y versión, por cuenta, centro de costo, servicio y mes; carga manual, importación Excel, copia del ejercicio anterior con porcentaje de ajuste y distribución estacional.</td><td>Se copia 2026 a 2027 con +30 % y estacionalidad de energía.</td></tr><tr><td>CP-CON-0144</td><td>RF-CON-144; M15 §5.14; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Aprobación y versionado del presupuesto (original y reformulaciones) con vigencia y auditoría.</td><td>La reformulación de julio conserva el original para comparar.</td></tr><tr><td>CP-CON-0145</td><td>RF-CON-145; M15 §5.14; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Compromisos: la OC aprobada (y opcionalmente contratos y SA autorizadas) compromete presupuesto; se libera al cancelar; se reduce al devengar la factura.</td><td>Cancelar una OC de ARS 40.000 libera ARS 40.000 de compromiso.</td></tr><tr><td>CP-CON-0146</td><td>RF-CON-146; M15 §5.14; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Control presupuestario al aprobar la OC: disponible = presupuesto − comprometido − devengado sin compromiso; política advertir, exigir autorización o bloquear.</td><td>Una OC que excede requiere autorización del aprobador.</td></tr><tr><td>CP-CON-0147</td><td>RF-CON-147; M15 §5.14; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Ejecución presupuestaria: presupuesto, comprometido, devengado y pagado como columnas separadas que no se suman entre sí, por cuenta, centro, servicio y mes, con desvíos.</td><td>El total de gastos no suma comprometido + devengado.</td></tr><tr><td>CP-CON-0148</td><td>RF-CON-148; M15 §5.14; PRO-O8-11</td><td>O8</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Vínculo con el flujo de fondos proyectado de TES (TES proyecta; CON aporta el presupuesto financiero).</td><td>El flujo de TES muestra columna &quot;presupuestado&quot;.</td></tr><tr><td>CP-CON-0149</td><td>RF-CON-149; M15 §5.14; PRO-O9-07</td><td>O9</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Proyección de costo laboral de SUE como fuente del presupuesto de sueldos.</td><td>Se importa la proyección de SUE como versión borrador.</td></tr></tbody></table><h3 id="_1-15-capital-social-contable-m15-§5-15" tabindex="-1">1.15 Capital social contable (M15 §5.15) <a class="header-anchor" href="#_1-15-capital-social-contable-m15-§5-15" aria-label="Permalink to &quot;1.15 Capital social contable (M15 §5.15)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CON-0150</td><td>RF-CON-150; M15 §5.15; PRO-O5-12</td><td>O5</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Cuentas de capital por rubro de capital y roles: movimientos de capital, capital a devolver, capital rescatado por socios incobrables, capital integrado, capital suscripto, ajuste de capital.</td><td>Cada rubro de capital tiene cuenta o aparece en el validador.</td></tr><tr><td>CP-CON-0151</td><td>RF-CON-151; M15 §5.15; PRO-O5-12</td><td>O5</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Asientos de suscripción, integración, reembolso, rescate, capitalización de retornos y ajuste de capital desde eventos de M17; las transferencias de capital entre asociados no generan asiento si la cuenta es la misma.</td><td>Transferir capital de un socio a otro no genera asiento; queda en el auxiliar de M17.</td></tr><tr><td>CP-CON-0161</td><td>RF-CON-161; M15 §5.15; PRO-O10-02</td><td>O10</td><td>Estándar</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Capital fuera del mínimo de O5: cuentas y asientos de capital a devolver, reembolso y rescate (también por socios incobrables), ajuste de capital, reservas, distribución de excedentes y capitalización de retornos (M-107…M-110, M-113…</td><td>En O5 un evento de rescate de M17 queda pendiente de configuración y no se contabiliza con una regla provisoria.</td></tr><tr><td>CP-CON-0162</td><td>RF-CON-162; RN-CON-125; M15 §5.15; PRO-O5-10</td><td>O5</td><td>Núcleo</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td><strong>Contabilidad por entidad jurídica</strong> (DEC-064, DEC-087): ejercicios, períodos, numeración de asientos, libro diario, mayores, sumas y saldos, libros rubricados, estados contables, ajuste por inflación y conciliaciones se llevan por…</td><td>Con dos entidades A y B, el asiento N.º 1 del ejercicio 2027 existe una vez en cada entidad; un cobro en la caja de A por ARS 5.000 de B deja en A deuda con B por 5.000 y en B crédito contra A por 5.000, y sumas y saldos de cada entidad balancean por separado.</td></tr><tr><td>CP-CON-0152</td><td>RF-CON-152; M15 §5.15; PRO-O10-02</td><td>O10</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Conciliación del auxiliar de capital con contabilidad y exposición del capital en el EEPN.</td><td>El EEPN muestra capital suscripto, integrado y a devolver.</td></tr></tbody></table><h3 id="_1-16-transversales-m15-§5-16" tabindex="-1">1.16 Transversales (M15 §5.16) <a class="header-anchor" href="#_1-16-transversales-m15-§5-16" aria-label="Permalink to &quot;1.16 Transversales (M15 §5.16)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>CP</th><th>Cubre</th><th>Ola</th><th>Prioridad</th><th>Tipo</th><th>Dado</th><th>Cuando</th><th>Entonces (resultado esperado)</th></tr></thead><tbody><tr><td>CP-CON-0153</td><td>RF-CON-153; M15 §5.16; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>seguridad</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Aislamiento por tenant de planes, asientos, simulaciones, presupuestos y exportaciones; todo índice comienza por <code>tenantId</code>.</td><td>Un usuario de TEN-002 recibe 404 al pedir un asiento de TEN-001.</td></tr><tr><td>CP-CON-0154</td><td>RF-CON-154; M15 §5.16; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Todas las etiquetas por clave de diccionario y renombrables por tenant (ej. &quot;Sección&quot; en lugar de &quot;Centro de costo&quot;).</td><td>El tenant cambia <code>dict:con.costCenter</code> a &quot;Sección&quot; y se refleja en todas las pantallas.</td></tr><tr><td>CP-CON-0155</td><td>RF-CON-155; M15 §5.16; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Única fuente de saldos: los renglones contabilizados; los saldos por cuenta/período/centro son una proyección reconstruible; no existen saldos editables.</td><td>Reconstruir la proyección produce los mismos saldos.</td></tr><tr><td>CP-CON-0156</td><td>RF-CON-156; M15 §5.16; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Rendimiento: contabilizar el lote de 100.000 facturas del ciclo en resumen dentro de la ventana operativa; mayores y sumas y saldos paginados con respuesta interactiva.</td><td>El resumen de 100.000 eventos termina sin bloquear la operación (job reanudable).</td></tr><tr><td>CP-CON-0157</td><td>RF-CON-157; M15 §5.16; PRO-O5-11</td><td>O5</td><td>Estándar</td><td>regla</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Tablero contable con estado de períodos, eventos pendientes, borradores, conciliaciones con diferencias, alertas de configuración y vencimientos de cierre.</td><td>El tablero muestra &quot;12 eventos pendientes de configuración&quot; con enlace.</td></tr><tr><td>CP-CON-0158</td><td>RF-CON-158; M15 §5.16; PRO-O11-05</td><td>O11</td><td>Estándar</td><td>funcional</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>IA solo propone: sugerir cuenta para un concepto nuevo, detectar asientos atípicos; nunca contabiliza ni aprueba.</td><td>La sugerencia requiere confirmación humana y se audita.</td></tr><tr><td>CP-CON-0159</td><td>RF-CON-159; M15 §5.16; PRO-O5-11</td><td>O5</td><td>Núcleo</td><td>seguridad</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Segregación de funciones: quien carga un ajuste por encima del umbral no lo aprueba; reapertura de ejercicio con doble autorización; anulación masiva con permiso específico.</td><td>El mismo usuario no puede cargar y aprobar un ajuste de ARS 500.000.</td></tr><tr><td>CP-CON-0160</td><td>RF-CON-160; M15 §5.16; PRO-O5-11</td><td>O5</td><td>Estándar</td><td>migración</td><td>TEN-001 (y TEN-002 si aplica) con datos ficticios y la configuración publicada</td><td>Migración repetible desde ProCoop de plan de cuentas, rubros, ejercicios, asientos, centros, reglas y parámetros-cuenta, con conciliación de sumas y saldos.</td><td>Las sumas y saldos migradas coinciden con ProCoop a la fecha de corte. Ola: los saldos de apertura migran en O5 y el resto del historial en O11 (antes <code>O11 (O5 para saldos de apertura)</code>).</td></tr></tbody></table><h2 id="_2-casos-por-escenario-y-criterio-de-aceptacion-con-id" tabindex="-1">2. Casos por escenario y criterio de aceptación con ID <a class="header-anchor" href="#_2-casos-por-escenario-y-criterio-de-aceptacion-con-id" aria-label="Permalink to &quot;2. Casos por escenario y criterio de aceptación con ID&quot;">​</a></h2><p><strong>CP-CON-5001 — ESC-01. Pago en exceso de ARS 2.000</strong></p><ul><li>Cubre: ESC-01; relacionados: CU-CON-02; M15 §17</li><li>Ola: O5 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Pago en exceso de ARS 2.000</li><li>Entonces Saldo a favor en <code>customerAdvances</code>, nunca ingreso; informe de anticipos coincide (CU-CON-02).</li></ul><p><strong>CP-CON-5002 — ESC-02. Reenvío del mismo evento económico (reintento del outbox)</strong></p><ul><li>Cubre: ESC-02; RF-CON-051; M15 §17</li><li>Ola: O5 · Prioridad: Núcleo · Tipo: integración</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Reenvío del mismo evento económico (reintento del outbox)</li><li>Entonces Un solo evento y un solo asiento (RF-CON-051).</li></ul><p><strong>CP-CON-5003 — ESC-03. Asiento manual en período cerrado</strong></p><ul><li>Cubre: ESC-03; M15 §17</li><li>Ola: O3 · Prioridad: Núcleo · Tipo: funcional</li><li>Precondiciones: ola O3 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Asiento manual en período cerrado</li><li>Entonces 409 con <code>dict:con.errors.periodClosed</code>; nada se graba.</li></ul><p><strong>CP-CON-5004 — ESC-04. Usuario sin <code>con.asientos.contabilizar</code> intenta contabilizar</strong></p><ul><li>Cubre: ESC-04; M15 §17</li><li>Ola: O5 · Prioridad: Núcleo · Tipo: seguridad</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001 y TEN-002; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Usuario sin <code>con.asientos.contabilizar</code> intenta contabilizar</li><li>Entonces 403; la acción no aparece en la UI.</li></ul><p><strong>CP-CON-5005 — ESC-05. Usuario del tenant A consulta un asiento del tenant B por id</strong></p><ul><li>Cubre: ESC-05; M15 §17</li><li>Ola: O4 · Prioridad: Núcleo · Tipo: seguridad</li><li>Precondiciones: ola O4 desplegada; tenant ficticio TEN-001 y TEN-002; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Usuario del tenant A consulta un asiento del tenant B por id</li><li>Entonces 404 (no revela existencia); los índices y consultas incluyen <code>tenantId</code>.</li></ul><p><strong>CP-CON-5006 — ESC-CON-06. Evento con concepto sin cuenta</strong></p><ul><li>Cubre: ESC-CON-06; M15 §17</li><li>Ola: O5 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Evento con concepto sin cuenta</li><li>Entonces Evento <code>pendingConfiguration</code>, documento de origen válido, cierre del período bloqueado hasta resolver.</li></ul><p><strong>CP-CON-5007 — ESC-CON-07. Asiento automático intentado editar</strong></p><ul><li>Cubre: ESC-CON-07; RN-CON-113; M15 §17</li><li>Ola: O5 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Asiento automático intentado editar</li><li>Entonces Rechazado; solo revertir y reprocesar (RN-CON-113).</li></ul><p><strong>CP-CON-5008 — ESC-CON-08. Anulación de una factura de período cerrado</strong></p><ul><li>Cubre: ESC-CON-08; M15 §17</li><li>Ola: O5 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Anulación de una factura de período cerrado</li><li>Entonces Contraasiento con fecha del período abierto; el original intacto.</li></ul><p><strong>CP-CON-5009 — ESC-CON-09. Lote de un rango ya contabilizado</strong></p><ul><li>Cubre: ESC-CON-09; M15 §17</li><li>Ola: O5 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Lote de un rango ya contabilizado</li><li>Entonces Sin asientos nuevos; informe &quot;0 eventos pendientes&quot;.</li></ul><p><strong>CP-CON-5010 — ESC-CON-10. Simulación ejecutada dos veces con los mismos insumos</strong></p><ul><li>Cubre: ESC-CON-10; M15 §17</li><li>Ola: O5 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Simulación ejecutada dos veces con los mismos insumos</li><li>Entonces Mismo <code>runHash</code> y resultados; ningún registro en <code>journalEntries</code>.</li></ul><p><strong>CP-CON-5011 — ESC-CON-11. Reporte oficial con escenario existente</strong></p><ul><li>Cubre: ESC-CON-11; M15 §17</li><li>Ola: O5 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Reporte oficial con escenario existente</li><li>Entonces Los importes simulados no aparecen en mayor, sumas y saldos ni estados.</li></ul><p><strong>CP-CON-5012 — ESC-CON-12. Reconstrucción de saldos</strong></p><ul><li>Cubre: ESC-CON-12; M15 §17</li><li>Ola: O5 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Reconstrucción de saldos</li><li>Entonces <code>ledgerBalances</code> reconstruido = proyección vigente; si difiere, alerta crítica.</li></ul><p><strong>CP-CON-5013 — ESC-CON-13. Conciliación de deudores al cierre del mes</strong></p><ul><li>Cubre: ESC-CON-13; M15 §17</li><li>Ola: O5 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Conciliación de deudores al cierre del mes</li><li>Entonces Auxiliar COB por servicio = cuenta de control por servicio, o diferencias clasificadas.</li></ul><p><strong>CP-CON-5014 — ESC-CON-14. Reapertura de ejercicio sin segundo aprobador</strong></p><ul><li>Cubre: ESC-CON-14; M15 §17</li><li>Ola: O5 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Reapertura de ejercicio sin segundo aprobador</li><li>Entonces Imposible; la solicitud queda pendiente.</li></ul><p><strong>CP-CON-5015 — ESC-CON-15. Unificación de cuentas</strong></p><ul><li>Cubre: ESC-CON-15; M15 §17</li><li>Ola: O5 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Unificación de cuentas</li><li>Entonces Movimientos, roles y reglas pasan al destino; mayor del destino = suma de ambos; origen <code>merged</code>.</li></ul><p><strong>CP-CON-5016 — ESC-CON-16. Distribución con modelo que no suma 100 %</strong></p><ul><li>Cubre: ESC-CON-16; M15 §17</li><li>Ola: O5 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Distribución con modelo que no suma 100 %</li><li>Entonces Rechazo en la configuración.</li></ul><p><strong>CP-CON-5017 — ESC-CON-17. Amortización revertida</strong></p><ul><li>Cubre: ESC-CON-17; M15 §17</li><li>Ola: O5 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Amortización revertida</li><li>Entonces STK revierte acumulados (EVT-CON-02); el bien no puede eliminarse si tiene amortizaciones contabilizadas.</li></ul><p><strong>CP-CON-5018 — ESC-CON-18. Cobro en caja con PRM-CON-025 = <code>onCashboxClosed</code></strong></p><ul><li>Cubre: ESC-CON-18; M15 §17</li><li>Ola: O5 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Cobro en caja con PRM-CON-025 = <code>onCashboxClosed</code></li><li>Entonces El asiento se genera al cerrar la caja, con el detalle de sus cobros.</li></ul><p><strong>CP-CON-5019 — ESC-CON-19. Falla de la base durante la contabilización</strong></p><ul><li>Cubre: ESC-CON-19; M15 §17</li><li>Ola: O5 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Falla de la base durante la contabilización</li><li>Entonces Transacción revertida; el evento queda <code>received</code> y se reintenta sin duplicar.</li></ul><p><strong>CP-CON-5020 — ESC-CON-20. Diferencia de redondeo de 0,03 en un resumen</strong></p><ul><li>Cubre: ESC-CON-20; M15 §17</li><li>Ola: O5 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Diferencia de redondeo de 0,03 en un resumen</li><li>Entonces Va a <code>billingRounding</code>; 0,06 con tolerancia 0,05 deja el evento en <code>error</code>.</li></ul><p><strong>CP-CON-5021 — ESC-CON-21. Token externo con <code>con.ext.saldos</code> pide asientos</strong></p><ul><li>Cubre: ESC-CON-21; M15 §17</li><li>Ola: O5 · Prioridad: Estándar · Tipo: seguridad</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001 y TEN-002; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Token externo con <code>con.ext.saldos</code> pide asientos</li><li>Entonces 403.</li></ul><p><strong>CP-CON-5022 — ESC-CON-22. Importación de asientos con cuenta agrupadora</strong></p><ul><li>Cubre: ESC-CON-22; M15 §17</li><li>Ola: O5 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Importación de asientos con cuenta agrupadora</li><li>Entonces Rechazo con fila y cuenta.</li></ul><p><strong>CP-CON-5023 — ESC-CON-23. Factura mayorista de energía ficticia por ARS 1.000.000 neto + IVA (HUE-ELE-01)</strong></p><ul><li>Cubre: ESC-CON-23; M15 §17</li><li>Ola: O5 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Factura mayorista de energía ficticia por ARS 1.000.000 neto + IVA (HUE-ELE-01)</li><li>Entonces Debe <code>wholesaleEnergyCost</code> 1.000.000 (servicio ELE) y <code>vatInput</code>; haber <code>accountsPayable</code>; ningún ingreso ni cargo al usuario.</li></ul><p><strong>CP-CON-5024 — ESC-CON-24. Liquidación de derechos de señales aprobada por ARS 180.000 y factura de la programadora por ARS 182.000 (HUE-TV-01)</strong></p><ul><li>Cubre: ESC-CON-24; M15 §17</li><li>Ola: O5 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Liquidación de derechos de señales aprobada por ARS 180.000 y factura de la programadora por ARS 182.000 (HUE-TV-01)</li><li>Entonces M-128 devenga 180.000; la factura cancela 180.000 de <code>signalRightsAccrued</code> y 2.000 van a <code>signalRightsCost</code>.</li></ul><p><strong>CP-CON-5025 — ESC-CON-25. Subsidio aprobado por ARS 300.000 con fondo de ARS 250.000 y PRM-CON-194 = <code>expense</code> (HUECO-SEP-03)</strong></p><ul><li>Cubre: ESC-CON-25; M15 §17</li><li>Ola: O5 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Subsidio aprobado por ARS 300.000 con fondo de ARS 250.000 y PRM-CON-194 = <code>expense</code> (HUECO-SEP-03)</li><li>Entonces Debe <code>socialSubsidyFund</code> 250.000 y <code>socialSubsidy</code> 50.000; haber <code>socialSubsidyPayable</code> 300.000; reprocesar EVT-SOC-04 no duplica.</li></ul><p><strong>CP-CON-5026 — ESC-CON-26. Depósito ORT-DEMO-01 de ARS 20.000 facturado y luego devuelto como crédito (HUECO-OTR-04)</strong></p><ul><li>Cubre: ESC-CON-26; M15 §17</li><li>Ola: O5 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Depósito ORT-DEMO-01 de ARS 20.000 facturado y luego devuelto como crédito (HUECO-OTR-04)</li><li>Entonces Al facturar: haber <code>guaranteesHeld</code> 20.000 (sin ingreso); al devolver: debe <code>guaranteesHeld</code> 20.000, haber <code>customerAdvances</code> 20.000.</li></ul><p><strong>CP-CON-5027 — ESC-CON-27. Derecho de sepultura facturado por ARS 600.000 con vigencia de 10 años y PRM-CON-193 = <code>deferredOverTerm</code> (HUECO-CEM-04)</strong></p><ul><li>Cubre: ESC-CON-27; M15 §17</li><li>Ola: O5 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Derecho de sepultura facturado por ARS 600.000 con vigencia de 10 años y PRM-CON-193 = <code>deferredOverTerm</code> (HUECO-CEM-04)</li><li>Entonces Al facturar: haber <code>burialRightDeferredRevenue</code> 600.000; JOB-CON-23 devenga ARS 5.000 por mes; con <code>atGrant</code> todo es ingreso del período.</li></ul><p><strong>CP-CON-5028 — ESC-CON-28. Tenant con entidades A y B; cobro único en la caja de A de ARS 8.000 de A y ARS 5.000 de B (DEC-087, M-136)</strong></p><ul><li>Cubre: ESC-CON-28; M15 §17</li><li>Ola: O5 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Tenant con entidades A y B; cobro único en la caja de A de ARS 8.000 de A y ARS 5.000 de B (DEC-087, M-136)</li><li>Entonces En A: debe caja 13.000, haber créditos por servicios 8.000 y <code>interEntityAccount</code> 5.000; en B: debe <code>interEntityAccount</code> 5.000, haber créditos por servicios 5.000; reprocesar el evento no duplica; cada entidad balancea sola.</li></ul><p><strong>CP-CON-5029 — ESC-CON-29. Factura con abono de ARS 10.000 y aporte de capital de ARS 2.000 (clase <code>capitalContribution</code>, RN-FIS-124)</strong></p><ul><li>Cubre: ESC-CON-29; RN-FIS-124; M15 §17</li><li>Ola: O5 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Factura con abono de ARS 10.000 y aporte de capital de ARS 2.000 (clase <code>capitalContribution</code>, RN-FIS-124)</li><li>Entonces El asiento M-01 imputa 10.000 a ingreso del servicio y el M-02 imputa 2.000 a capital social; ningún importe del aporte va a <code>rol:serviceRevenue</code>.</li></ul><p><strong>CP-CON-5030 — ESC-CON-30. Cierre del período <code>2027-03</code> de la entidad A (CTR-DAT-31)</strong></p><ul><li>Cubre: ESC-CON-30; M15 §17</li><li>Ola: O5 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Cierre del período <code>2027-03</code> de la entidad A (CTR-DAT-31)</li><li>Entonces EVT-CON-07 con <code>legalEntityId</code> de A, <code>period = 2027-03</code> y <code>sequence = 3</code> (ejercicio que inicia en enero); el período de B sigue abierto.</li></ul><p><strong>CP-CON-5031 — ESC-CON-31. Factura con servicio ARS 12.100, aporte al fondo ARS 1.000 (<code>subsidyFundContribution</code>) y depósito ARS 50.000 (<code>guaranteeDeposit</code>), valores…</strong></p><ul><li>Cubre: ESC-CON-31; RN-CON-126; M15 §17</li><li>Ola: O5 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Factura con servicio ARS 12.100, aporte al fondo ARS 1.000 (<code>subsidyFundContribution</code>) y depósito ARS 50.000 (<code>guaranteeDeposit</code>), valores ficticios, con reglamento que constituye el fondo con aportes (RN-CON-126)</li><li>Entonces Haber <code>rol:serviceRevenue</code> (neto) e IVA, <code>rol:socialSubsidyFund</code> 1.000 y <code>rol:guaranteesHeld</code> 50.000; ninguna clase especial cae en ingreso por la cascada; un renglón con clase desconocida queda pendiente sin asiento provisorio.</li></ul><h2 id="_3-casos-por-caso-de-uso-cu" tabindex="-1">3. Casos por caso de uso (CU) <a class="header-anchor" href="#_3-casos-por-caso-de-uso-cu" aria-label="Permalink to &quot;3. Casos por caso de uso (CU)&quot;">​</a></h2><p><strong>CP-CON-8001 — CU-22. Pago digital con comisión (BASE §22)</strong></p><ul><li>Cubre: CU-22; M15 §16</li><li>Ola: O5 · Prioridad: Núcleo · Tipo: integración</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando 1. Ana Pérez (ASO-001) paga ARS 8.000 por pasarela; COB publica <code>cob.payment.confirmed</code> (M-22). Asiento: Debe <code>collectionsPendingBankCredit</code> 8.000 / Haber <code>billingReceivable</code> (servicio de la factura) 8.000. 2. TES registra la acreditación neta (M-23): Debe Banco 7.840, <code>gatewayCommissions</code> 160 / Haber <code>collectionsPendingBankCredit</code> 8.000. ASI-DEMO-001 en la precarga muestra la forma condensada (Debe Banco 7.840 + Comisiones 160 / Haber Créditos por servicios 8.000) que resulta de sumar ambos pasos. 3.</li><li>Entonces La cuenta puente queda en cero; desde el asiento se abre el recibo y la liquidación de la pasarela. Si la acreditación no llega, la cuenta puente muestra el pendiente por canal y la conciliación lo lista.</li></ul><p><strong>CP-CON-8002 — CU-ERP-01. Planes alternativos y simulación de tarifa (BASE §55)</strong></p><ul><li>Cubre: CU-ERP-01; M15 §16</li><li>Ola: O5 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Planes alternativos y simulación de tarifa (BASE §55)</li><li>Entonces Definición dueña: este anexo (planes de cuentas y simulación son de M15). T10 la cita para el reporte REP-CON-004. 1. En PC-OPER-01 los ingresos del mes suman 38.000 en &quot;Ingresos por servicios&quot;. 2. En PC-ALT-01 la equivalencia separa por servicio: Agua 13.000, Internet 25.000 (proyección JOB-CON-10). 3. SIM-ERP-001 aplica tarifa +10 %: Agua 14.300, Internet 27.500, total 41.800, con marca de simulación; los libros oficiales siguen en 38.000.</li></ul><p><strong>CP-CON-8003 — CU-CON-01. Resultado por servicio con costos comunes (BASE §75)</strong></p><ul><li>Cubre: CU-CON-01; M15 §16</li><li>Ola: O5 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando 1. Facturas de ASO-001: Agua 13.000 y Internet 25.000 (M-01). Cobro de 5.000 imputado a Agua (M-20). Saldo del auxiliar 33.000 = cuenta de control 33.000 (conciliación <code>balanced</code>). 2. Costos directos: Agua 6.000 (CC-AG), Internet 12.000 (CC-INT); comunes 4.000 en CC-ADM. 3. Corrida con DIST-DEMO-25-75: Agua recibe 1.000, Internet 3.000.</li><li>Entonces Agua 13.000 − 6.000 − 1.000 = 6.000; Internet 25.000 − 12.000 − 3.000 = 10.000; total 16.000 (igual al resultado contable 38.000 − 22.000). 4. SIM-CON-001 con reparto 50/50: Agua 5.000, Internet 11.000, total 16.000 sin tocar libros.</li></ul><p><strong>CP-CON-8004 — CU-OPE-01. Compra de módems con compromiso (BASE §78, parte contable)</strong></p><ul><li>Cubre: CU-OPE-01; M15 §16</li><li>Ola: O5 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Compra de módems con compromiso (BASE §78, parte contable)</li><li>Entonces Definición dueña: M12 «CU-OPE-01 — Compra de módems por servicio». Aquí solo el tramo contable. 1. OC-DEMO-002 por 2 módems × 20.000 = 40.000 aprobada: compromiso 40.000 en el presupuesto de CC-INT (sin asiento, M-55). 2. Recepción (M-56): Debe Stock módems 40.000 / Haber <code>goodsPendingDelivery</code> 40.000. 3. Factura del proveedor neto 40.000 + IVA 8.400 (M-57): Debe <code>goodsPendingDelivery</code> 40.000, <code>vatInput</code> 8.400 / Haber <code>accountsPayable</code> 48.400. El compromiso pasa a devengado; la ejecución muestra comprometido 0, devengado 40.000.</li></ul><p><strong>CP-CON-8005 — CU-104. Asiento de sueldos (BASE §104, parte contable)</strong></p><ul><li>Cubre: CU-104; M15 §16</li><li>Ola: O5 · Prioridad: Núcleo · Tipo: regla</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Asiento de sueldos (BASE §104, parte contable)</li><li>Entonces Definición dueña: M16 «CU-104 — Liquidación mensual de una cooperativa eléctrica». Aquí solo el asiento; los importes son un ejemplo de la forma del asiento y no reemplazan los datos ficticios de M16. 1. SUE aprueba la liquidación de octubre 2026 (<code>sue.payrollRun.approved</code>, M-96) con imputación por centro: Distribución 60 %, Administración 30 %, Internet 10 %. 2. Ejemplo: remuneraciones 1.000.000, contribuciones patronales 240.000, aportes y retenciones 170.000, sindicato 20.000. Asiento: Debe Sueldos 1.000.000 y Cargas sociales 240.000 (distribuidos 60/30/10) / Haber <code>payrollPayable</code> 810.000, <code>socialSecurityPayable</code> 410.000 (aportes 170.000 + contribuciones 240.000)…</li></ul><p><strong>CP-CON-8006 — CU-FIS-01. Pago a proveedor con retención (BASE §61, parte contable)</strong></p><ul><li>Cubre: CU-FIS-01; M15 §16</li><li>Ola: O5 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Pago a proveedor con retención (BASE §61, parte contable)</li><li>Entonces Definición dueña: M06 «CU-FIS-01 — Retención en un pago a proveedor». Aquí solo el tramo contable, con los importes de M06 y M12 (corrección 05-11-2026: antes factura de 121.000 y pago de 119.000). Factura de 100.000 de PROV-DEMO-001; la OP aplica la retención RET-DEMO-001 de 2.000 (M-48) y paga 98.000 (M-58): Debe <code>accountsPayable</code> 100.000 / Haber Banco 98.000, <code>withholdingsPayable</code> 2.000. El depósito de la retención (M-51) cancela el pasivo.</li></ul><p><strong>CP-CON-8007 — CU-CON-02. Pago en exceso (ESC-01)</strong></p><ul><li>Cubre: CU-CON-02; relacionados: ESC-01; M15 §16</li><li>Ola: O5 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Pago en exceso (ESC-01)</li><li>Entonces ASO-001 paga 10.000 con una deuda de 8.000: Debe Caja 10.000 / Haber <code>billingReceivable</code> 8.000, <code>customerAdvances</code> 2.000 (M-20, M-25). El informe de anticipos al 31-10-2026 lista 2.000 y coincide con la cuenta. La factura siguiente consume el saldo (M-26).</li></ul><p><strong>CP-CON-8008 — CU-CON-03. Resumen diario de cobranza</strong></p><ul><li>Cubre: CU-CON-03; M15 §16</li><li>Ola: O5 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Resumen diario de cobranza</li><li>Entonces Modo <code>dailySummary</code> para COB. El 15-10-2026 llegan 1.200 cobros en 3 cajas y 2 entes. JOB-CON-02 agrupa por día, servicio y medio: genera un asiento con un renglón por servicio en <code>billingReceivable</code> y uno por caja/ente; el usuario revisa en PAN-CON-17 y confirma. Re-ejecutar el día no duplica (los eventos ya están <code>posted</code>). Con PRM-CON-024 activo y una caja abierta, el lote se detiene y la muestra.</li></ul><p><strong>CP-CON-8009 — CU-CON-04. Servicio nuevo sin cuenta</strong></p><ul><li>Cubre: CU-CON-04; M15 §16</li><li>Ola: O5 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Servicio nuevo sin cuenta</li><li>Entonces Se publica el servicio &quot;TV&quot; sin regla de ventas: con PRM-CON-017 = <code>block</code> la publicación se detiene con el faltante. Si se publicó con <code>warn</code>, la primera factura emitida deja su evento en <code>pendingConfiguration</code> (EVT-CON-04), la factura sigue válida para el socio, el contador asigna la cuenta desde el enlace de la bandeja, JOB-CON-03 reprocesa y el período puede cerrarse.</li></ul><p><strong>CP-CON-8010 — CU-CON-05. Compra con IVA computable por sección</strong></p><ul><li>Cubre: CU-CON-05; M15 §16</li><li>Ola: O5 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Compra con IVA computable por sección</li><li>Entonces Factura de proveedor neto 100.000 + IVA 21.000 = 121.000, imputada 50 % a Distribución (IVA computable 60 %) y 50 % a Administración (100 %). Con PRM-CON-030 activo: Debe Gastos Distribución 50.000 + IVA no computable 4.200 (40 % de 10.500), Gastos Administración 50.000, <code>vatInput</code> 16.800 (6.300 + 10.500) / Haber <code>accountsPayable</code> 121.000.</li></ul><p><strong>CP-CON-8011 — CU-CON-06. Convenio de pago con intereses</strong></p><ul><li>Cubre: CU-CON-06; M15 §16</li><li>Ola: O5 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Convenio de pago con intereses</li><li>Entonces Deuda vencida 30.000 refinanciada en 3 cuotas con interés total 3.000 (M-37): Debe <code>refinancingReceivable</code> 33.000 / Haber <code>billingReceivable</code> 30.000, <code>deferredFinancingInterest</code> 3.000. Al facturar cada cuota (M-38): Debe <code>deferredFinancingInterest</code> 1.000 / Haber <code>interestIncome</code> 1.000. Si el convenio cae tras la primera cuota (M-39), se restituye la deuda y se revierte el interés no devengado (2.000).</li></ul><p><strong>CP-CON-8012 — CU-CON-07. Cierre del ejercicio 2026</strong></p><ul><li>Cubre: CU-CON-07; M15 §16</li><li>Ola: O5 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Cierre del ejercicio 2026</li><li>Entonces 1. Los doce períodos están cerrados; el ajuste por inflación está contabilizado. 2. JOB-CON-05 genera la refundición (cierra todas las cuentas de ingresos y egresos del ejercicio y lleva la diferencia a <code>resultAllocation</code> o a los destinos de <code>resultTargets</code>), el cierre patrimonial y la apertura 2027. 3. Vista previa: todas las cuentas de resultado en cero; el contador confirma; EVT-CON-09 informa el resultado a M17 para la asamblea.</li></ul><p><strong>CP-CON-8013 — CU-CON-08. Reapertura de período</strong></p><ul><li>Cubre: CU-CON-08; M15 §16</li><li>Ola: O5 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Reapertura de período</li><li>Entonces El 10-11-2026 aparece una factura de compra de octubre. El contador solicita reabrir octubre para compras con motivo y plazo 2 días; el gerente aprueba (T11); se registra; el período vuelve a <code>closed</code> al vencer el plazo o a mano. Todo queda en el historial.</li></ul><p><strong>CP-CON-8014 — CU-CON-09. Ajuste por inflación</strong></p><ul><li>Cubre: CU-CON-09; M15 §16</li><li>Ola: O5 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Ajuste por inflación</li><li>Entonces Un terreno de 100.000 incorporado con índice 100; índice al cierre 150. Coeficiente 1,5; ajuste 50.000: Debe Terreno 50.000 / Haber <code>inflationAdjustment</code> 50.000. Si falta el índice de un mes, la corrida aborta indicando el mes.</li></ul><p><strong>CP-CON-8015 — CU-CON-10. Capital social</strong></p><ul><li>Cubre: CU-CON-10; M15 §16</li><li>Ola: O5 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Capital social</li><li>Entonces Suscripción de 10 cuotas de 1.000 al afiliarse (M-105): Debe <code>capitalSubscribedReceivable</code> 10.000 / Haber <code>capitalMovements</code> 10.000. Integración de 2.000 en la factura (M-02, M-106) y cobro: el capital integrado no aparece como ingreso. Rescate aprobado de 2.000 (M-108) y pago (M-109).</li></ul><p><strong>CP-CON-8016 — CU-CON-11. Exceso presupuestario</strong></p><ul><li>Cubre: CU-CON-11; M15 §16</li><li>Ola: O5 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Exceso presupuestario</li><li>Entonces CC-INT tiene disponible 30.000; una OC de 40.000 dispara <code>con.commitment.exceeded</code>; con política <code>authorize</code> la OC queda esperando la autorización del gerente; aprobada, el compromiso registra el exceso autorizado.</li></ul><p><strong>CP-CON-8017 — CU-CON-12. Importación del estudio contable</strong></p><ul><li>Cubre: CU-CON-12; M15 §16</li><li>Ola: O5 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Importación del estudio contable</li><li>Entonces El estudio envía un XLSX con 3 asientos de ajuste; uno desbalanceado: la importación rechaza el archivo completo indicando la fila. Corregido, se importan como borradores y el contador los contabiliza.</li></ul><p><strong>CP-CON-8018 — CU-CON-13. Transcripción a libro rubricado</strong></p><ul><li>Cubre: CU-CON-13; M15 §16</li><li>Ola: O5 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Transcripción a libro rubricado</li><li>Entonces Libro Diario N.º 3, hojas 1 a 500, 50 líneas por hoja. Se transcriben los asientos 1 a 420 de 2026 en las hojas 1 a 37; los asientos transcriptos ya no admiten anulación (solo contraasiento) ni renumeración.</li></ul><p><strong>CP-CON-8019 — CU-CON-14. Amortización y reversión</strong></p><ul><li>Cubre: CU-CON-14; M15 §16</li><li>Ola: O5 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Amortización y reversión</li><li>Entonces STK publica la amortización de octubre (M-70) de un camión 70 % Distribución / 30 % Administración por 30.000: Debe Amortizaciones 21.000 (CC-DIS) y 9.000 (CC-ADM) / Haber Amortización acumulada rodados 30.000. Al revertir la corrida, CON registra el contraasiento y emite EVT-CON-02; STK devuelve los acumulados al 30-09.</li></ul><p><strong>CP-CON-8020 — CU-CON-15. Distribución de excedentes</strong></p><ul><li>Cubre: CU-CON-15; M15 §16</li><li>Ola: O5 · Prioridad: Estándar · Tipo: regla</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Distribución de excedentes</li><li>Entonces Excedente repartible aprobado por asamblea (M-113): Debe <code>unassignedSurplus</code> / Haber reservas y fondos con los porcentajes de PRM-CON-060, interés a cuotas y retornos a pagar; el resultado con no asociados va a <code>specialReserve</code>. Los retornos capitalizados (M-114) aumentan el capital del asociado en M17.</li></ul><p><strong>CP-CON-8021 — CU-CON-16. Diferencia en conciliación de bancos</strong></p><ul><li>Cubre: CU-CON-16; M15 §16</li><li>Ola: O5 · Prioridad: Estándar · Tipo: funcional</li><li>Precondiciones: ola O5 desplegada; tenant ficticio TEN-001; configuración publicada.</li><li>Datos de prueba: Datos ficticios del escenario; tenant TEN-001 (y TEN-002 para aislamiento).</li><li>Dado el tenant ficticio TEN-001 con los datos de prueba indicados</li><li>Cuando Diferencia en conciliación de bancos</li><li>Entonces La conciliación diaria muestra banco contable 500.000 vs auxiliar TES 499.000: diferencia de corte (gasto bancario registrado en TES al día siguiente). El contador la clasifica como <code>cutoff</code> y queda <code>explained</code>; al día siguiente la diferencia desaparece.</li></ul>',144)])])}const C=t(d,[["render",n]]);export{O as __pageData,C as default};
